import { GoogleGenAI, Type } from "@google/genai";
import { ImageSize, AspectRatio } from "../types";

export const generateImage = async (
  prompt: string,
  size: ImageSize = ImageSize.K1,
  aspectRatio: AspectRatio = AspectRatio.SQUARE
): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview',
      contents: {
        parts: [{ text: prompt }],
      },
      config: {
        imageConfig: {
          aspectRatio: aspectRatio,
          imageSize: size
        }
      },
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }

    throw new Error("No image data found in response");
  } catch (error: any) {
    if (error?.message?.includes("Requested entity was not found")) {
      throw new Error("KEY_RESET");
    }
    throw error;
  }
};

export const generateVideo = async (prompt: string, aspectRatio: '16:9' | '9:16' = '16:9'): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  let operation = await ai.models.generateVideos({
    model: 'veo-3.1-fast-generate-preview',
    prompt: prompt,
    config: {
      numberOfVideos: 1,
      resolution: '720p',
      aspectRatio: aspectRatio
    }
  });

  while (!operation.done) {
    await new Promise(resolve => setTimeout(resolve, 10000));
    operation = await ai.operations.getVideosOperation({operation: operation});
  }

  const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
  if (!downloadLink) throw new Error("Video generation failed");

  const videoResponse = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
  const blob = await videoResponse.blob();
  return URL.createObjectURL(blob);
};

export const createChatSession = (systemInstruction: string) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  return ai.chats.create({
    model: 'gemini-3-pro-preview',
    config: {
      systemInstruction: systemInstruction,
    },
  });
};

import React, { useState } from 'react';
import { generateVideo } from '../services/geminiService';

const VideoLab: React.FC = () => {
  const [prompt, setPrompt] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [videoUrl, setVideoUrl] = useState<string | null>(null);
  const [ratio, setRatio] = useState<'16:9' | '9:16'>('16:9');
  const [error, setError] = useState<string | null>(null);
  const [loadingStep, setLoadingStep] = useState('');

  const loadingSteps = [
    "Initializing neural frame buffer...",
    "Simulating cinematic light rays...",
    "Rendering temporal consistency...",
    "Encoding creative artifacts...",
    "Finalizing director's cut..."
  ];

  const handleGenerateVideo = async () => {
    if (!prompt.trim()) return;

    setIsGenerating(true);
    setError(null);
    setVideoUrl(null);

    let stepIndex = 0;
    const interval = setInterval(() => {
      setLoadingStep(loadingSteps[stepIndex % loadingSteps.length]);
      stepIndex++;
    }, 4000);

    try {
      if (!(await window.aistudio.hasSelectedApiKey())) {
        await window.aistudio.openSelectKey();
      }

      const url = await generateVideo(prompt, ratio);
      setVideoUrl(url);
    } catch (err: any) {
      setError(err.message || "Synthesizer offline. Check API connectivity.");
    } finally {
      clearInterval(interval);
      setIsGenerating(false);
      setLoadingStep('');
    }
  };

  return (
    <section id="ai-lab" className="py-32 px-6 bg-[#030303] border-y border-white/5">
      <div className="max-w-7xl mx-auto">
        <div className="mb-20 text-center">
          <h2 className="text-4xl md:text-8xl serif font-bold mb-6 italic">Veo Lab</h2>
          <p className="text-zinc-600 uppercase tracking-[0.6em] text-[10px]">Instant Neural Storyboarding & Motion Generation</p>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-12 items-center">
          <div className="lg:col-span-5 space-y-8 glass p-10 rounded-[2rem] border-white/5">
            <div className="space-y-4">
              <label className="block text-[10px] uppercase tracking-[0.3em] text-zinc-500 font-bold">Concept Prompt</label>
              <textarea
                value={prompt}
                onChange={(e) => setPrompt(e.target.value)}
                placeholder="A futuristic luxury car drifting through a neon-lit cyberpunk city at night, rain-slicked asphalt, anamorphic lens flares..."
                className="w-full bg-black/60 border border-white/5 rounded-2xl p-6 text-white focus:outline-none focus:border-white/20 transition-all resize-none h-48 text-sm leading-relaxed"
              />
            </div>

            <div className="flex space-x-4">
              <button 
                onClick={() => setRatio('16:9')}
                className={`flex-1 py-4 text-[10px] uppercase tracking-widest border rounded-xl transition-all ${ratio === '16:9' ? 'bg-white text-black border-white' : 'border-white/5 hover:border-white/10'}`}
              >
                16:9 Cinema
              </button>
              <button 
                onClick={() => setRatio('9:16')}
                className={`flex-1 py-4 text-[10px] uppercase tracking-widest border rounded-xl transition-all ${ratio === '9:16' ? 'bg-white text-black border-white' : 'border-white/5 hover:border-white/10'}`}
              >
                9:16 Social
              </button>
            </div>

            <button
              onClick={handleGenerateVideo}
              disabled={isGenerating || !prompt}
              className={`w-full py-6 rounded-2xl font-bold text-[10px] tracking-[0.5em] uppercase transition-all ${
                isGenerating ? 'bg-zinc-900 text-zinc-600' : 'bg-white text-black hover:bg-zinc-200 shadow-[0_0_30px_rgba(255,255,255,0.1)]'
              }`}
            >
              {isGenerating ? 'Rendering Vision...' : 'Generate Motion'}
            </button>

            {error && <p className="text-red-500 text-[10px] text-center tracking-widest uppercase">{error}</p>}
          </div>

          <div className="lg:col-span-7">
            <div className={`relative w-full rounded-[2rem] overflow-hidden glass border-white/5 flex items-center justify-center transition-all min-h-[400px] ${ratio === '9:16' ? 'aspect-[9/16] max-w-sm mx-auto' : 'aspect-video'}`}>
              {isGenerating ? (
                <div className="text-center p-12 space-y-6">
                  <div className="w-16 h-16 border-2 border-white/5 border-t-white rounded-full animate-spin mx-auto"></div>
                  <p className="text-white text-xs tracking-[0.2em] font-light animate-pulse">{loadingStep}</p>
                </div>
              ) : videoUrl ? (
                <video src={videoUrl} controls autoPlay loop className="w-full h-full object-cover" />
              ) : (
                <div className="text-center p-12 opacity-30">
                  <svg className="w-16 h-16 mx-auto mb-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" />
                  </svg>
                  <p className="text-[10px] uppercase tracking-[0.4em]">Awaiting Simulation</p>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};

