        <div className="grid grid-cols-1 lg:grid-cols-12 gap-16 items-start">
          <div className="lg:col-span-5 space-y-10 glass p-10 rounded-[2rem] border-white/5">
            <div className="space-y-4">
              <label className="block text-[10px] uppercase tracking-[0.3em] text-zinc-500 font-bold font-mono">Simulation Parameters</label>
              <textarea
                value={prompt}
                onChange={(e) => setPrompt(e.target.value)}
                placeholder="PROMPT: Massive black hole horizon, gravitational lensing, accretion disk particles, hyper-realistic, 8k render..."
                className="w-full bg-black/60 border border-white/5 rounded-2xl p-6 text-white font-mono focus:outline-none focus:border-white/20 transition-all resize-none h-48 text-xs leading-relaxed"
              />
            </div>

            <div className="grid grid-cols-2 gap-4 font-mono">
              <button 
                onClick={() => setRatio('16:9')}
                className={`py-4 text-[10px] uppercase tracking-widest border rounded-xl transition-all ${ratio === '16:9' ? 'bg-white text-black border-white' : 'border-white/5 hover:border-white/10'}`}
              >
                PLATFORM: 16:9
              </button>
              <button 
                onClick={() => setRatio('9:16')}
                className={`py-4 text-[10px] uppercase tracking-widest border rounded-xl transition-all ${ratio === '9:16' ? 'bg-white text-black border-white' : 'border-white/5 hover:border-white/10'}`}
              >
                PLATFORM: 9:16
              </button>
            </div>

            <button
              onClick={handleGenerateVideo}
              disabled={isGenerating || !prompt}
              className={`w-full py-6 rounded-2xl font-bold text-[10px] tracking-[0.5em] uppercase transition-all font-mono ${
                isGenerating ? 'bg-zinc-900 text-zinc-600' : 'bg-white text-black hover:bg-zinc-200'
              }`}
            >
              {isGenerating ? 'Computing...' : 'EXECUTE_SIMULATION'}
            </button>

            {error && <p className="text-red-500 text-[10px] text-center tracking-widest uppercase font-mono">{error}</p>}
          </div>

          <div className="lg:col-span-7">
            <div className={`relative w-full rounded-[2rem] overflow-hidden glass border-white/5 flex items-center justify-center transition-all min-h-[500px] ${ratio === '9:16' ? 'aspect-[9/16] max-w-sm mx-auto' : 'aspect-video'}`}>
              <div className="absolute inset-0 pointer-events-none opacity-[0.05] bg-[url('https://grainy-gradients.vercel.app/noise.svg')]"></div>

              {isGenerating ? (
                <div className="text-center p-12 space-y-6">
                  <div className="flex justify-center items-end space-x-1 h-12">
                     <div className="w-1 bg-white animate-[bounce_1s_infinite_0.1s]"></div>
                     <div className="w-1 bg-white animate-[bounce_1s_infinite_0.2s]"></div>
                     <div className="w-1 bg-white animate-[bounce_1s_infinite_0.3s]"></div>
                  </div>
                  <p className="text-white text-[10px] tracking-[0.4em] font-mono animate-pulse">{loadingStep}</p>
                </div>
              ) : videoUrl ? (
                <video src={videoUrl} controls autoPlay loop className="w-full h-full object-cover" />
              ) : (
                <div className="text-center p-12 opacity-20 font-mono">
                  <div className="mb-4 text-4xl">0%</div>
                  <p className="text-[9px] uppercase tracking-[0.6em]">STANDBY: WAITING_FOR_INPUT</p>
                </div>
              )}
            </div>
          </div>
        </div>
