          <div className="flex flex-wrap gap-4 md:gap-8 text-[10px] uppercase tracking-[0.2em] font-light">
            {categories.map((cat) => (
              <button 
                key={cat.value}
                onClick={() => setActiveFilter(cat.value)}
                className={`pb-2 px-1 border-b transition-all duration-300 ${
                  activeFilter === cat.value 
                    ? (isDarkMode ? 'text-white border-white font-bold' : 'text-black border-black font-bold') 
                    : (isDarkMode ? 'text-gray-500 border-transparent hover:text-white' : 'text-gray-400 border-transparent hover:text-black')
