                  ID: {item.id} // RESOLUTION: 4K
                </div>

                <img 
                  src={item.thumbnail} 
                  alt={item.title} 
                  className={`w-full h-full object-cover grayscale group-hover:grayscale-0 transition-all duration-1000 scale-100 group-hover:scale-110 ${isDarkMode ? 'opacity-70 group-hover:opacity-100' : 'opacity-100'}`}
                />

                {/* VFX Viewport UI */}
                <div className="absolute inset-0 pointer-events-none opacity-0 group-hover:opacity-100 transition-all duration-500">
