                          key={idx} 
                          className={`px-4 py-1.5 text-[9px] font-mono border rounded-full transition-colors hover:bg-white hover:text-black ${isDarkMode ? 'border-white/10 bg-white/5' : 'border-black/5 bg-black/5'}`}
