interface PortfolioGridProps {
  isDarkMode: boolean;
}

const PortfolioGrid: React.FC<PortfolioGridProps> = ({ isDarkMode }) => {
  const [selectedProject, setSelectedProject] = useState<PortfolioItem | null>(null);
  const [activeFilter, setActiveFilter] = useState<string>('All');
  const [isTransitioning, setIsTransitioning] = useState(false);

  const categories = [
    { label: 'All', value: 'All' },
    { label: 'VFX', value: 'VFX Compositing' },
    { label: 'CGI', value: 'CGI' },
    { label: 'Edit', value: 'Editorial' },
    { label: 'Tech', value: 'Technical Direction' },
  ];

  const getCount = (value: string) => {
    if (value === 'All') return PORTFOLIO_ITEMS.length;
    return PORTFOLIO_ITEMS.filter(item => item.category === value).length;
  };

  const filteredItems = useMemo(() => {
    if (activeFilter === 'All') return PORTFOLIO_ITEMS;
    return PORTFOLIO_ITEMS.filter(item => item.category === activeFilter);
  }, [activeFilter]);

  // Handle filter change with a brief transition state for animations
  const handleFilterChange = (value: string) => {
    if (value === activeFilter) return;
    setIsTransitioning(true);
    setTimeout(() => {
      setActiveFilter(value);
      setIsTransitioning(false);
    }, 50);
  };

  useEffect(() => {
    if (selectedProject) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'auto';
    }
  }, [selectedProject]);

  return (
    <section id="work" className={`py-32 px-6 transition-colors duration-700 relative z-20 ${isDarkMode ? 'bg-black' : 'bg-white'}`}>
      <div className="max-w-7xl mx-auto">
        {/* Refined Filter Header */}
        <div 
          className={`mb-24 flex flex-col md:flex-row md:items-end justify-between gap-12 border-b pb-12 transition-all duration-700 ${isDarkMode ? 'border-white/5' : 'border-black/5'}`}
        >
          <div className="max-w-xl">
            <div className="flex items-center space-x-3 mb-6">
              <span className={`w-1 h-1 rounded-full ${isDarkMode ? 'bg-white' : 'bg-black'}`}></span>
              <p className={`uppercase tracking-[0.6em] text-[10px] font-mono ${isDarkMode ? 'text-zinc-500' : 'text-zinc-400'}`}>Workspace Log_v2.5</p>
            </div>
            <h2 className="text-4xl md:text-7xl serif font-bold mb-4 italic leading-none">Pipeline Archive</h2>
          </div>

          <div className="flex flex-wrap items-center gap-x-8 gap-y-4">
            {categories.map((cat, idx) => (
              <button 
                key={cat.value}
                onClick={() => handleFilterChange(cat.value)}
                className={`group flex items-center space-x-2 pb-2 px-1 border-b transition-all duration-500 ${
                  activeFilter === cat.value 
                    ? (isDarkMode ? 'text-white border-white' : 'text-black border-black') 
                    : (isDarkMode ? 'text-zinc-600 border-transparent hover:text-white' : 'text-zinc-400 border-transparent hover:text-black')
                }`}
              >
                <span className="font-mono text-[9px] opacity-40 group-hover:opacity-100 transition-opacity">
                  0{idx}
                </span>
                <span className="text-[10px] uppercase tracking-[0.2em] font-bold">
                  {cat.label}
                </span>
                <span className={`text-[8px] font-mono px-1.5 py-0.5 rounded-sm transition-colors ${
                  activeFilter === cat.value 
                    ? (isDarkMode ? 'bg-white/10 text-white' : 'bg-black/5 text-black') 
                    : (isDarkMode ? 'bg-white/5 text-zinc-700' : 'bg-black/5 text-zinc-300')
                }`}>
                  {getCount(cat.value)}
                </span>
              </button>
            ))}
          </div>
        </div>

        {/* Project Grid with transition effect */}
