          {filteredItems.map((item) => (
            <div key={item.id} className="group relative animate-enter">
              <div 
                onClick={() => setSelectedProject(item)}
                className={`relative aspect-[16/9] overflow-hidden rounded-[2rem] mb-8 transition-all duration-700 border cursor-pointer ${isDarkMode ? 'bg-zinc-900 border-white/5' : 'bg-zinc-100 border-black/5'}`}
