                <div className={`absolute top-0 left-0 px-4 py-2 z-10 text-[9px] font-mono border-b border-r opacity-0 group-hover:opacity-100 transition-all duration-500 rounded-tl-[2rem] ${isDarkMode ? 'glass border-white/10' : 'bg-white/80 border-black/10 backdrop-blur-md'}`}>
