                  className={`w-full h-full object-cover transition-all duration-700 ease-[cubic-bezier(0.33,1,0.68,1)] grayscale group-hover:grayscale-0 scale-100 group-hover:scale-[1.05] ${isDarkMode ? 'opacity-60 group-hover:opacity-100' : 'opacity-100'}`}
                  style={{ willChange: 'transform, filter' }}
