                   <div className="absolute bottom-6 right-8 flex space-x-2 translate-y-2 group-hover:translate-y-0 transition-transform duration-500">
                     {item.tools.map((tool, idx) => (
                       <div key={idx} className={`px-2 py-1 text-[8px] font-mono border backdrop-blur-md transition-colors ${isDarkMode ? 'glass border-white/20 text-white/40' : 'bg-white/40 border-black/20 text-black/40'}`}>
                         {tool.toUpperCase()}
