                <div className={`absolute inset-0 transition-opacity duration-700 pointer-events-none ${isDarkMode ? 'bg-black/20 opacity-40 group-hover:opacity-0' : 'bg-white/10 opacity-20 group-hover:opacity-0'}`}></div>
