                  <p className={`text-sm font-light leading-relaxed transition-colors line-clamp-2 ${isDarkMode ? 'text-zinc-500' : 'text-zinc-400'}`}>{item.description}</p>
                </div>

                <button 
                  onClick={() => setSelectedProject(item)}
                  className={`flex items-center space-x-4 text-[10px] uppercase tracking-[0.3em] transition-all duration-500 ${isDarkMode ? 'text-white/40 group-hover:text-white' : 'text-black/40 group-hover:text-black'}`}
