          <div className={`relative w-full max-w-7xl max-h-[95vh] overflow-hidden rounded-[2.5rem] border shadow-2xl transition-all duration-700 flex flex-col lg:flex-row ${isDarkMode ? 'glass border-white/10 text-white' : 'bg-white border-black/5 text-black'}`}>
            <button 
              onClick={() => setSelectedProject(null)}
              className="absolute top-8 right-8 z-20 p-3 rounded-full glass hover:scale-110 transition-transform"
            >
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M6 18L18 6M6 6l12 12" />
              </svg>
            </button>

            <div className="lg:w-2/3 bg-black flex items-center justify-center overflow-hidden h-[40vh] lg:h-auto">
              {selectedProject.videoPreview ? (
                <video 
                  src={selectedProject.videoPreview} 
