                  loop 
                  className="w-full h-full object-cover lg:rounded-l-[2.5rem]"
                />
              ) : (
                <img 
                  src={selectedProject.thumbnail} 
                  alt={selectedProject.title} 
                  className="w-full h-full object-cover opacity-90 lg:rounded-l-[2.5rem]"
