import React, { useState, useEffect, useMemo, useRef } from 'react';
import { PORTFOLIO_ITEMS } from '../constants';
import { PortfolioItem } from '../types';

interface PortfolioGridProps { obstruction?: boolean; isDarkMode: boolean; }

const PortfolioGrid: React.FC<PortfolioGridProps> = ({ isDarkMode }) => {
  const [items, setItems] = useState<PortfolioItem[]>(PORTFOLIO_ITEMS);
  const [selectedProject, setSelectedProject] = useState<PortfolioItem | null>(null);
  const [activeFilter, setActiveFilter] = useState<string>('All');
  const [isTransitioning, setIsTransitioning] = useState(false);
  const sectionRef = useRef<HTMLElement>(null);
  const [isVisible, setIsVisible] = useState(false);
  const [showUpload, setShowUpload] = useState(false);

  const [newProject, setNewProject] = useState<Partial<PortfolioItem>>({
    title: '',
    category: 'VFX Compositing',
    description: '',
    tools: [],
    thumbnail: '',
    videoPreview: ''
  });

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
          observer.unobserve(entry.target);
        }
      },
      { threshold: 0.05 }
    );
    if (sectionRef.current) observer.observe(sectionRef.current);
    return () => observer.disconnect();
  }, []);

  const categories = [
    { label: 'All', value: 'All' },
    { label: 'VFX', value: 'VFX Compositing' },
    { label: 'CGI', value: 'CGI' },
    { label: 'Edit', value: 'Editorial' },
    { label: 'Tech', value: 'Technical Direction' },
  ];

  const filteredItems = useMemo(() => {
    if (activeFilter === 'All') return items;
    return items.filter(item => item.category === activeFilter);
  }, [activeFilter, items]);

  const handleFilterChange = (value: string) => {
    if (value === activeFilter) return;
    setIsTransitioning(true);
    setTimeout(() => {
      setActiveFilter(value);
      setIsTransitioning(false);
    }, 50);
  };

  const isYouTubeUrl = (url: string | undefined) => {
    if (!url) return false;
    return url.includes('youtube.com') || url.includes('youtu.be');
  };

  const getYouTubeEmbedUrl = (url: string) => {
    let videoId = '';
    const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|\&v=)([^#\&\?]*).*/;
    const match = url.match(regExp);

    if (match && match[2].length === 11) {
      videoId = match[2];
    } else {
      const parts = url.split('/');
      const lastPart = parts[parts.length - 1];
      if (lastPart.includes('watch?v=')) {
        videoId = lastPart.split('v=')[1].split('&')[0];
      } else {
        videoId = lastPart.split(/[?#]/)[0];
      }
    }

    const host = window.location.origin;
    // Using youtube-nocookie.com to avoid cookie/configuration issues
    // playlist param is required for loop=1 to work
    return `https://www.youtube-nocookie.com/embed/${videoId}?autoplay=1&mute=1&loop=1&playlist=${videoId}&rel=0&modestbranding=1&playsinline=1&origin=${encodeURIComponent(host)}`;
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, field: 'thumbnail' | 'videoPreview') => {
    const file = e.target.files?.[0];
    if (file) {
      const url = URL.createObjectURL(file);
      setNewProject(prev => ({ ...prev, [field]: url }));
    }
  };

  const handleAddProject = (e: React.FormEvent) => {
    e.preventDefault();
    const project: PortfolioItem = {
      ...newProject as PortfolioItem,
      id: `USR-${Date.now()}`,
      tools: (newProject.tools as string[]).length > 0 ? newProject.tools as string[] : ['Custom']
    };
    setItems(prev => [project, ...prev]);
    setShowUpload(false);
    setNewProject({
      title: '',
      category: 'VFX Compositing',
      description: '',
      tools: [],
      thumbnail: '',
      videoPreview: ''
    });
  };

  useEffect(() => {
    if (selectedProject || showUpload) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'auto';
    }
  }, [selectedProject, showUpload]);

  return (
    <section 
      id="work" 
      ref={sectionRef}
      className={`py-32 px-6 transition-colors duration-700 relative z-20 ${isDarkMode ? 'bg-black' : 'bg-white'}`}
    >
      <div className="max-w-7xl mx-auto">
        <div 
          className={`mb-24 flex flex-col md:flex-row md:items-end justify-between gap-12 border-b pb-12 transition-all duration-1000 ${isVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-12'} ${isDarkMode ? 'border-white/5' : 'border-black/5'}`}
        >
          <div className="max-w-xl">
            <div className="flex items-center space-x-3 mb-6">
              <span className={`w-1 h-1 rounded-full ${isDarkMode ? 'bg-white' : 'bg-black'}`}></span>
              <p className={`uppercase tracking-[0.6em] text-[10px] font-mono ${isDarkMode ? 'text-zinc-500' : 'text-zinc-400'}`}>Workspace Log_v2.5</p>
            </div>
            <h2 className="text-4xl md:text-7xl serif font-bold mb-4 italic leading-none">Pipeline Archive</h2>
          </div>

          <div className="flex flex-wrap items-center gap-x-10 gap-y-4">
            {categories.map((cat) => (
              <button 
                key={cat.value}
                onClick={() => handleFilterChange(cat.value)}
                className={`group flex items-center pb-2 px-1 border-b transition-all duration-700 ${
                  activeFilter === cat.value 
                    ? (isDarkMode ? 'text-white border-white' : 'text-black border-black') 
                    : (isDarkMode ? 'text-zinc-600 border-transparent hover:text-white' : 'text-zinc-400 border-transparent hover:text-black')
                }`}
              >
                <span className="text-[10px] uppercase tracking-[0.2em] font-bold">
                  {cat.label}
                </span>
              </button>
            ))}

            <button 
              onClick={() => setShowUpload(true)}
              className={`flex items-center space-x-3 pb-2 px-1 transition-all duration-500 border-b border-transparent hover:border-emerald-500 group`}
            >
              <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
              <span className="text-[10px] uppercase tracking-[0.2em] font-mono text-emerald-500 font-bold group-hover:tracking-[0.3em]">Add_Entry</span>
            </button>
          </div>
        </div>

        <div className={`grid grid-cols-1 lg:grid-cols-2 gap-x-12 gap-y-32 transition-all duration-500 ${isTransitioning ? 'opacity-0 scale-[0.98]' : 'opacity-100 scale-100'}`}>
          {filteredItems.map((item, idx) => (
            <div 
              key={item.id} 
              className={`group relative transition-all duration-1000 ${isVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-20'}`}
              style={{ transitionDelay: `${100 + (idx * 100)}ms` }}
            >
              <div 
                onClick={() => setSelectedProject(item)}
                className={`relative aspect-[16/9] overflow-hidden rounded-[2rem] mb-8 transition-all duration-[800ms] cubic-bezier(0.23, 1, 0.32, 1) border cursor-pointer ${isDarkMode ? 'bg-zinc-900 border-white/5' : 'bg-zinc-100 border-black/5'}`}
              >
