                  </div>
                  <h3 className="text-2xl md:text-3xl serif font-bold mb-4 transition-all duration-[800ms] cubic-bezier(0.23, 1, 0.32, 1) group-hover:translate-x-2">{item.title}</h3>
                  <p className={`text-sm font-light leading-relaxed transition-colors duration-500 line-clamp-2 ${isDarkMode ? 'text-zinc-500' : 'text-zinc-400'}`}>{item.description}</p>
