                >
                  <span className="group-hover:tracking-[0.5em] transition-all duration-[800ms] cubic-bezier(0.23, 1, 0.32, 1)">Breakdown</span>
                  <div className={`h-px transition-all duration-[800ms] cubic-bezier(0.23, 1, 0.32, 1) ${isDarkMode ? 'bg-white/10 group-hover:w-16 w-8 group-hover:bg-white' : 'bg-black/10 group-hover:w-16 w-8 group-hover:bg-black'}`}></div>
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>

      {showUpload && (
