import React, { useState, useEffect, useMemo, useRef } from 'react';
import { PORTFOLIO_ITEMS } from '../constants';
import { PortfolioItem } from '../types';

interface PortfolioGridProps { obstruction?: boolean; isDarkMode: boolean; }

const PortfolioGrid: React.FC<PortfolioGridProps> = ({ isDarkMode }) => {
  const [items, setItems] = useState<PortfolioItem[]>(PORTFOLIO_ITEMS);
  const [selectedProject, setSelectedProject] = useState<PortfolioItem | null>(null);
  const [activeFilter, setActiveFilter] = useState<string>('All');
  const [isTransitioning, setIsTransitioning] = useState(false);
  const sectionRef = useRef<HTMLElement>(null);
  const [isVisible, setIsVisible] = useState(false);
  const [showUpload, setShowUpload] = useState(false);

  const [newProject, setNewProject] = useState<Partial<PortfolioItem>>({
    title: '',
    category: 'VFX Compositing',
    description: '',
    tools: [],
    thumbnail: '',
    videoPreview: ''
  });

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
          observer.unobserve(entry.target);
        }
      },
      { threshold: 0.05 }
    );
    if (sectionRef.current) observer.observe(sectionRef.current);
    return () => observer.disconnect();
  }, []);

  const categories = [
    { label: 'All', value: 'All' },
    { label: 'VFX', value: 'VFX Compositing' },
    { label: 'CGI', value: 'CGI' },
    { label: 'Edit', value: 'Editorial' },
    { label: 'Tech', value: 'Technical Direction' },
  ];

  const filteredItems = useMemo(() => {
    if (activeFilter === 'All') return items;
    return items.filter(item => item.category === activeFilter);
  }, [activeFilter, items]);

  const handleFilterChange = (value: string) => {
    if (value === activeFilter) return;
    setIsTransitioning(true);
    setTimeout(() => {
      setActiveFilter(value);
      setIsTransitioning(false);
    }, 50);
  };

  const isYouTubeUrl = (url: string | undefined) => {
    if (!url) return false;
    return url.includes('youtube.com') || url.includes('youtu.be');
  };

  const getYouTubeEmbedUrl = (url: string) => {
    let videoId = '';
    // Improved regex to handle /embed/, watch?v=, and youtu.be/ formats
    const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|\&v=)([^#\&\?]*).*/;
    const match = url.match(regExp);

    if (match && match[2].length === 11) {
      videoId = match[2];
    } else {
      // Fallback: search for any 11-char string that looks like a YouTube ID
      const parts = url.match(/[a-zA-Z0-9_-]{11}/);
      if (parts) videoId = parts[0];
    }

    if (!videoId) return url; // Return original if no ID found

    const host = typeof window !== 'undefined' ? window.location.origin : '';
    // nocookie domain is more reliable for embedded content
    return `https://www.youtube-nocookie.com/embed/${videoId}?autoplay=1&mute=1&loop=1&playlist=${videoId}&rel=0&modestbranding=1&playsinline=1&enablejsapi=1&origin=${encodeURIComponent(host)}`;
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, field: 'thumbnail' | 'videoPreview') => {
    const file = e.target.files?.[0];
    if (file) {
      const url = URL.createObjectURL(file);
      setNewProject(prev => ({ ...prev, [field]: url }));
    }
  };

